"""Build an offline, credential-free viewer from actual recorded evidence."""
import html,json,re,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from wallex_agent.evaluation import provenance

out=Path('artifacts/wallex-demo');out.mkdir(parents=True,exist_ok=True)
study=json.loads(Path('reports/final_strategy/results.json').read_text())
latest=sorted(Path('reports/final_online').glob('*/summary.json'))[-1]
online=json.loads(latest.read_text());cutoff=json.loads(Path('reports/cutoff_demo/summary.json').read_text())
access_path=Path('reports/credit_readonly_verification.json')
if not access_path.exists():access_path=Path('reports/FINAL_ACCESS_STATUS.json')
access=json.loads(access_path.read_text())
tests=Path('reports/final_tests.log').read_text();match=re.search(r'Ran (\d+) tests in ([\d.]+)s\s+OK',tests)
assert match,'final tests not successful'
esc=lambda x:html.escape(str(x))
pretty=lambda x:'<pre>'+esc(json.dumps(x,ensure_ascii=False,indent=2))+'</pre>'
rows=[]
for r in study['results']:
 if r['scenario']!='base_assumed':continue
 rows.append('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in [r['segment'],r['strategy'],f"{r['net_return']*100:.3f}%",r['trade_count'],f"{r['max_drawdown']*100:.3f}%",'—' if r['sell_fill_win_rate'] is None else f"{r['sell_fill_win_rate']*100:.1f}%",f"{r['turnover_TMN']:.0f}"])+'</tr>')
body='''<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>کاو — شواهد واقعی عامل Wallex</title><style>body{margin:0;background:#0b1120;color:#e3eaf8;font:18px/1.9 Tahoma,Arial,sans-serif}main{max-width:1280px;margin:auto;padding:32px}h1,h2{color:#7dd3fc}nav{position:sticky;top:0;background:#172033;padding:12px;z-index:1}a{color:#a5e4ff;margin:12px}section{padding:24px;border:1px solid #334155;margin:24px 0;border-radius:12px;scroll-margin-top:65px}pre{direction:ltr;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.6 monospace;background:#030712;padding:18px}table{border-collapse:collapse;width:100%;direction:ltr;font-size:15px}td,th{padding:8px;border:1px solid #475569}strong{color:#fcd34d}.badge{padding:12px;background:#1e293b;border-radius:10px;margin:12px 0}.table{overflow-x:auto}small{color:#bdcbe1}</style><nav><a href="#status">وضعیت</a><a href="#research">بازار و استراتژی</a><a href="#ai">AI واقعی</a><a href="#shadow">سایه</a><a href="#cutoff">پایان دوره</a><a href="#reproduce">بازتولید</a></nav><main><h1>کاو — عامل پژوهشی و معاملاتی Wallex</h1><p>نمایش شواهد ثبت‌شده؛ این صفحه سفارش یا API جدیدی اجرا نمی‌کند.</p>'''
body+='<section id="status"><p>زمان آخرین بازآزمایی فقط‌خواندنی: '+esc(access.get('observed_at'))+'</p><h2>مرز واقعیت و آمادگی</h2><div class="badge">'+esc(match.group(1))+' تست موفق · '+esc(online['real_inference_count'])+' inference واقعی BoxAPI · صفر سفارش واقعی</div><p><strong>معاملهٔ زنده و انتشار GitHub غیرفعال‌اند.</strong> زیرحساب هکاتون با نوع prop، فعال و غیرمعلق و موجودی کل/در دسترس۵میلیون تومان با GET مستند احراز شد؛ کلید برای خواندن معتبر است. start balance، expiry، فهرست بازارها و مسیر سفارش هنوز کامل نیست. پاسخ GET تاریخچهٔ اعتبار HTTP '+esc(access.get('history',{}).get('http_status'))+' برای تاریخچهٔ اعتبار بود؛ خواندن پایه و کیف پول200 دادند؛ کد خطای پکیج1201 است. تاریخ و timezone پایان معاملات نامعلوم است.</p><p>موفقیت خواندن کیف پول را موفقیت متادیتای پکیج یا route سفارش معرفی نمی‌کنیم؛ هیچ سفارش آزمایشی ثبت نشده است.</p></section>'
body+='<section id="research"><h2>هزینه، رژیم بازار و انتخاب صادقانه</h2><p>۷۵ مقایسه روی train/validation، پنج بخش عمومی BTC/ETH/USDT؛ هزینهٔ پایهٔ فرضی رفت‌وبرگشت ۰٫۹٪ به‌اضافهٔ حاشیهٔ edge. maker/taker حساب واقعی احراز نشده است. خروجی نهایی: <strong>cash</strong>. ستون win rate فقط fillهای فروش محقق‌شده است، نه تمام round tripها. این جدول فقط validation است.</p><div class="table"><table><tr><th>Segment</th><th>Strategy</th><th>Net return</th><th>Fills</th><th>Max DD</th><th>Sell-fill win</th><th>Turnover TMN</th></tr>'+''.join(rows)+'</table></div><details><summary>پوشش داده و علت عدم ورود مدل</summary>'+pretty(study['diagnostics'])+'</details><p>۱۵ کندل تازه جداگانه seal شد و ارزیابی نشد؛ برای ادعای عملکرد کافی نیست. holdout قدیمی قبلاً دیده شده بود.</p></section>'
body+='<section id="ai"><h2>BoxAPI واقعی در تصمیم</h2><p>مدل openai/gpt-5.4-mini؛ schema JSON معتبر، timeout/retry محدود، token usage و journal. ورودی مدل فقط دادهٔ عمومی بازار است؛ ابزار سفارش ندارد.</p><p><strong>بازپخش تاریخی بخش آموزش؛ معاملهٔ زنده نیست.</strong> اولین نامزد زمانی momentum، بدون انتخاب بر اساس سود آینده، از target حدود۲۰٪ به صفر پس از AI/gate رسید. خروجی‌های زیر تصمیم ثبت‌شده پس از gate اعتماد هستند؛ raw خروجیِ کم‌اعتماد در این اجرای تاریخی نگهداری نشده بود و ثبت آن برای اجراهای بعد افزوده شد.</p>'+pretty(online.get('historical_training_candidate'))+'</section>'
body+='<section id="shadow"><h2>دادهٔ جاری واقعی، پول مجازی</h2><p>دو چرخهٔ محلی بازار؛ دو بررسی واقعی AI؛ HOLD و بدون fill. این آزمون چنددقیقه‌ای پایداری سه‌روزه یا اتصال از منطقهٔ Liara را ثابت نمی‌کند. order book واقعی این اجرا احراز نشد؛ liquidity مدل حجم کندل است. درخواست عمومی عمق روی host مستند جدید ConnectError داد.</p>'+pretty(online['shadow'])+'<p>موجودی مجازی ۵٬۰۰۰٬۰۰۰ تومان، بازده و افت صفر با صفر معامله؛ این سود یا نتیجهٔ حساب واقعی نیست.</p></section>'
body+='<section id="cutoff"><h2>شبیه‌سازی واقعیِ کد پایان دوره</h2><p><strong>تمام قیمت‌ها و زمان‌های این بخش مصنوعی‌اند؛ endpoint والکس استفاده نشده است.</strong> deadline نامعلوم → توقف، قبل buffer → اجازهٔ ورودی، در buffer → تطبیق/لغو سفارش نیمه‌پر و فروش مجازی، پایان → تأیید تومان و گزارش مانده. سود مصنوعی این fixture شواهد استراتژی نیست.</p>'+pretty(cutoff)+'</section>'
body+='<section id="reproduce"><h2>راهنمای اجرای مجدد</h2>'+pretty({'offline_tests':'.venv/bin/python -m unittest discover -s tests -v','study':'.venv/bin/python scripts/final_strategy_study.py','cutoff_simulation':'.venv/bin/python scripts/cutoff_demo.py','readonly_auth_only':'.venv/bin/python -m wallex_agent.credit --online','online_AI_may_cost':'.venv/bin/python scripts/final_online_evidence.py --online','live':'BLOCKED; no production broker','source':provenance()})+'<p>کلید یا .env در این viewer نیست. گزارش‌ها تاریخی‌اند؛ کلیک روی بخش‌ها عملیات ابری یا معامله ایجاد نمی‌کند. GitHub منتشر نشده و ویدئو از همین شواهد تاریخی تهیه می‌شود؛ فاقد معاملهٔ زنده است.</p></section></main></html>'
(out/'index.html').write_text(body)
print(json.dumps({'viewer':str(out/'index.html'),'evidence':str(latest),'offline':True,'live_orders':False}))
